<?php
require_once __DIR__.'/../includes/auth.php';
$u=require_role(['provider','business']);$field=$u['role']==='provider'?'provider_id':'business_id';$pg=pagination_window(20,40);release_session_lock();
$sql="SELECT r.id,r.customer_id,r.category_id,r.service_id,r.request_type,r.title,r.location_text,r.preferred_date,r.status,r.created_at,cu.name customer_name,c.name category_name,s.name service_name
FROM service_requests r JOIN users cu ON cu.id=r.customer_id JOIN categories c ON c.id=r.category_id LEFT JOIN services s ON s.id=r.service_id
WHERE r.$field=? ORDER BY r.created_at DESC,r.id DESC LIMIT ".($pg['per']+1)." OFFSET ".$pg['offset'];
$q=db()->prepare($sql);$q->execute([(int)$u['id']]);$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);$pageTitle='Service Requests — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-5"><h1 class="fw-bold">Service Requests</h1><p class="text-muted">Requests sent directly to you or claimed by your account.</p><?php if(!$rows):?><div class="soft-card text-center p-5"><h3>No service requests on this page.</h3><p class="text-muted mb-0">New direct requests will appear here.</p></div><?php else:?><?php foreach($rows as $r):?><div class="soft-card p-4 mb-3"><div class="d-flex justify-content-between gap-3"><div><div class="small text-muted">From <?=e($r['customer_name'])?> · <?=e($r['service_name']?:$r['category_name'])?></div><h3 class="h5"><?=e($r['title'])?></h3><div><?=e($r['location_text'])?></div></div><span class="badge request-status status-<?=e($r['status'])?> align-self-start"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></div><a class="btn btn-sm btn-primary mt-3" href="<?=e(base_url('request-details.php?id='.$r['id']))?>">Open Request</a></div><?php endforeach;?><?=pagination_nav($pg['page'],$hasNext)?><?php endif;?></div><?php require __DIR__.'/../includes/footer.php';?>
